script:
(function () {
  'use strict';
  // ===== Tax figures: tax year 2026 =====
  // Ordinary brackets, capital gains breakpoints and standard deductions: IRS Rev. Proc. 2025-32,
  //   sections 4.01, 4.03 and 4.14 (as amended by P.L. 119-21).
  // AMT exemption ($90,100 unmarried / $140,200 joint / $70,100 separate), 28% rate threshold
  //   ($244,500; $122,250 separate) and phase-out start ($500,000 / $1,000,000 / $500,000):
  //   Rev. Proc. 2025-32 section 4.10. Phase-out rate 50% from 2026: IRC 55(d)(3) as amended by
  //   P.L. 119-21 (consistent with the Rev. Proc. complete phase-out amounts, e.g. 500,000 + 2 x 90,100).
  // Capital loss limit $3,000 ($1,500 separate): IRC 1211(b). Net investment income tax 3.8%: IRC 1411.
  // ISO and NSO treatment: IRS Pub. 525 (statutory and nonstatutory stock options).
  var TAX_YEAR = 2026;
  var BRACKETS = { // upper limit of each band; rates 10, 12, 22, 24, 32, 35, 37%
    single: [12400, 50400, 105700, 201775, 256225, 640600],
    mfj: [24800, 100800, 211400, 403550, 512450, 768700],
    hoh: [17700, 67450, 105700, 201750, 256200, 640600],
    mfs: [12400, 50400, 105700, 201775, 256225, 384350]
  };
  var RATES = [0.10, 0.12, 0.22, 0.24, 0.32, 0.35, 0.37];
  var CG_BREAKS = { single: [49450, 545500], mfj: [98900, 613700], hoh: [66200, 579600], mfs: [49450, 306850] };
  var STANDARD_DEDUCTION = { single: 16100, mfj: 32200, hoh: 24150, mfs: 16100 };
  var LOSS_LIMIT = { single: 3000, mfj: 3000, hoh: 3000, mfs: 1500 };
  var AMT_EXEMPTION = { single: 90100, hoh: 90100, mfj: 140200, mfs: 70100 };
  var AMT_PHASEOUT_START = { single: 500000, hoh: 500000, mfj: 1000000, mfs: 500000 };
  var AMT_PHASEOUT_RATE = 0.5;
  var AMT_28_START = { single: 244500, hoh: 244500, mfj: 244500, mfs: 122250 };
  var NIIT_RATE = 0.038;
  // ======================================
  // Method (per share: strike K, price now P0, target price PT; n options):
  //   Same-day exercise and sale at PT: spread max(0, PT - K) x n is ordinary income (NSO wages,
  //     or an ISO disqualifying disposition, which has no payroll tax).
  //   Exercise now, sell at PT more than a year later (two tax years):
  //     NSO - ordinary income max(0, P0 - K) x n at exercise (+ payroll tax); basis max(P0, K);
  //       long-term gain or loss (PT - basis) x n at sale.
  //     ISO (holding periods met) - no regular tax at exercise; long-term gain (PT - K) x n at sale.
  //       AMT adjustment = max(0, P0 - K) x n in the exercise year. Rough AMT estimate:
  //       AMTI = other taxable income + standard deduction + adjustment; exemption phased out at
  //       50%; 26% / 28% rates; extra AMT = AMT(with) - AMT(without), versus regular tax.
  //   Exercise now, sell at PT within a year (one tax year): NSO as above but the sale gain is
  //     short-term; ISO disqualifying - gain (PT - K) x n, ordinary up to the exercise spread, rest
  //     short-term capital gain; a loss is all capital.
  //   Federal tax is incremental: tax(other income + this income) - tax(other income), with
  //   long-term gains stacked on top at 0/15/20% and net capital losses deductible up to $3,000.
  //   State tax = flat rate x (ordinary income + net capital gain, not below zero).
  // Verified (Node, scratch tests, against hand calculations): single, $100,000 other taxable
  //   income, 1,000 options, strike $10, today $25, target $40, 5% state, 7.65% payroll:
  //   NSO same-day -> $30,000 ordinary, federal $7,086 (5,700 x 22% + 24,300 x 24%), payroll
  //   $2,295, state $1,500, after tax $19,119. NSO exercise today, sell after a year -> $15,000
  //   ordinary ($3,486) + $15,000 long-term at 15% ($2,250) = $5,736 federal, payroll $1,148.
  //   ISO same plan -> $30,000 long-term, $4,500 federal; AMT adjustment $15,000, AMTI $131,100,
  //   tentative minimum tax $10,660 < regular tax $16,712 -> no AMT. 20,000 ISOs -> long-term
  //   $600,000 taxed $97,725 (445,500 x 15% + 154,500 x 20%); AMTI $416,100, base $326,000,
  //   TMT $86,390 (244,500 x 26% + 81,500 x 28%) - $16,712 = $69,678 extra AMT.
  //   ISO sold within a year -> $15,000 ordinary + $15,000 short-term, $7,086, no payroll tax.
  //   NSO sold after a year at $20 -> $5,000 long-term loss, $3,000 deducted: federal
  //   $3,486 - $660 = $2,826. NIIT on $30,000 of gains = $1,140.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  var price = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });

  function num(id) {
    var el = document.getElementById(id);
    var v = el ? parseFloat(el.value) : NaN;
    return isNaN(v) ? NaN : v;
  }
  function set(id, text) { var el = document.getElementById(id); if (el) el.textContent = text; }
  function signed(v) { return v < -0.5 ? '−' + money.format(-v) : money.format(Math.max(0, v)); }

  function ordinaryTax(income, status) {
    var limits = BRACKETS[status], tax = 0, lower = 0;
    for (var i = 0; i < RATES.length; i++) {
      var upper = i < limits.length ? limits[i] : Infinity;
      if (income > lower) tax += (Math.min(income, upper) - lower) * RATES[i];
      lower = upper;
    }
    return tax;
  }

  // Federal income tax on ordinary taxable income plus short- and long-term capital gain/loss.
  function federal(status, ordinary, st, lt) {
    var net = st + lt, pref = 0, ordGain = 0, deduction = 0;
    if (net >= 0) { pref = lt > 0 ? Math.min(lt, net) : 0; ordGain = net - pref; }
    else deduction = Math.min(-net, LOSS_LIMIT[status]);
    var taxable = Math.max(0, ordinary + ordGain + pref - deduction);
    var gains = Math.min(pref, taxable), base = taxable - gains, b = CG_BREAKS[status];
    var mid = Math.max(0, Math.min(taxable, b[1]) - Math.max(base, b[0]));
    var top = Math.max(0, taxable - Math.max(base, b[1]));
    return Math.min(ordinaryTax(base, status) + 0.15 * mid + 0.20 * top, ordinaryTax(taxable, status));
  }

  function amt(status, taxable, adjustment) {
    var amti = taxable + STANDARD_DEDUCTION[status] + adjustment;
    var exemption = Math.max(0, AMT_EXEMPTION[status] - AMT_PHASEOUT_RATE * Math.max(0, amti - AMT_PHASEOUT_START[status]));
    var base = Math.max(0, amti - exemption), cut = AMT_28_START[status];
    var tmt = base <= cut ? 0.26 * base : 0.26 * cut + 0.28 * (base - cut);
    return Math.max(0, tmt - ordinaryTax(taxable, status));
  }

  // Taxes for exercising and selling n options under the chosen plan.
  function outcome(o, n, PT) {
    var K = o.strike, P0 = o.price, r = { ordinary: 0, st: 0, lt: 0, fed: 0, payroll: 0, state: 0, niit: 0,
      amtAdj: 0, amt: 0, pretax: 0, tax: 0, after: 0, exercised: true };
    if (n <= 0) return r;
    var base = federal(o.status, o.income, 0, 0);
    if (o.plan === 'same') {
      var spread = Math.max(0, PT - K) * n;
      if (spread <= 0) { r.exercised = false; return r; }
      r.ordinary = spread;
      r.pretax = spread;
      r.fed = federal(o.status, o.income + spread, 0, 0) - base;
      if (o.type === 'nso') r.payroll = spread * o.payroll;
    } else {
      var exSpread = Math.max(0, P0 - K) * n, gain = (PT - K) * n;
      r.pretax = gain;
      if (o.type === 'nso') {
        r.ordinary = exSpread;
        r.payroll = exSpread * o.payroll;
        var capital = (PT - Math.max(P0, K)) * n;
        if (o.plan === 'long') {
          r.lt = capital;
          r.fed = (federal(o.status, o.income + exSpread, 0, 0) - base) + (federal(o.status, o.income, 0, capital) - base);
        } else {
          r.st = capital;
          r.fed = federal(o.status, o.income + exSpread, capital, 0) - base;
        }
      } else if (o.plan === 'long') {
        r.lt = gain;
        r.fed = federal(o.status, o.income, 0, gain) - base;
        r.amtAdj = exSpread;
        r.amt = Math.max(0, amt(o.status, o.income, exSpread) - amt(o.status, o.income, 0));
      } else {
        if (gain > 0) { r.ordinary = Math.min(gain, exSpread); r.st = gain - r.ordinary; } else r.st = gain;
        r.fed = federal(o.status, o.income + r.ordinary, r.st, 0) - base;
      }
    }
    var capNet = r.st + r.lt;
    r.state = o.state * Math.max(0, r.ordinary + capNet);
    if (o.niit) r.niit = NIIT_RATE * Math.max(0, capNet);
    r.tax = r.fed + r.payroll + r.state + r.niit;
    r.after = r.pretax - r.tax;
    return r;
  }

  function update() {
    var o = {
      type: document.getElementById('soType').value, plan: document.getElementById('soPlan').value,
      status: document.getElementById('soStatus').value, niit: document.getElementById('soNiit').checked,
      total: num('soTotal'), vested: num('soVested'), strike: num('soStrike'), price: num('soPrice'),
      target: num('soTarget'), income: num('soIncome'), state: num('soState') / 100, payroll: num('soPayroll') / 100
    };
    document.getElementById('soPayrollWrap').hidden = o.type !== 'nso';
    var error = document.getElementById('soError'), msg = '';
    if ([o.total, o.vested, o.strike, o.price, o.target, o.income, o.state, o.payroll].some(isNaN)) msg = 'Fill in every field with a number.';
    else if (o.total < 1 || o.total > 1e7 || Math.floor(o.total) !== o.total) msg = 'Enter a whole number of options from 1 to 10,000,000.';
    else if (o.vested < 0 || o.vested > o.total || Math.floor(o.vested) !== o.vested) msg = 'Vested options must be a whole number from 0 up to the total.';
    else if (o.strike < 0 || o.price < 0 || o.target < 0 || o.strike > 1e6 || o.price > 1e6 || o.target > 1e6) msg = 'Enter prices from $0 to $1,000,000.';
    else if (o.income < 0) msg = 'Other taxable income cannot be negative.';
    else if (o.state < 0 || o.state > 0.15) msg = 'Enter a state tax rate from 0% to 15%.';
    else if (o.payroll < 0 || o.payroll > 0.2) msg = 'Enter a payroll tax rate from 0% to 20%.';
    error.hidden = !msg;
    error.textContent = msg;
    if (msg) return;

    var all = outcome(o, o.total, o.target), vest = outcome(o, o.vested, o.target);
    var nowSpread = Math.max(0, o.price - o.strike);
    set('soAllPretax', signed(all.pretax));
    set('soVestedPretax', signed(vest.pretax));
    set('soUnvestedPretax', signed(all.pretax - vest.pretax));
    set('soAllAfter', signed(all.after));
    set('soNowValue', money.format(nowSpread * o.total) + ' (' + money.format(nowSpread * o.vested) + ' vested)');
    set('soCost', money.format(all.exercised ? o.strike * o.total : 0));
    set('soOrdinary', money.format(all.ordinary));
    set('soCapital', signed(all.st + all.lt) + (all.st + all.lt !== 0 ? (all.lt !== 0 ? ' long-term' : ' short-term') : ''));
    set('soFed', signed(all.fed));
    set('soPayrollTax', money.format(all.payroll));
    set('soStateTax', money.format(all.state));
    set('soNiitTax', money.format(all.niit));
    set('soTax', signed(all.tax));

    var isoLong = o.type === 'iso' && o.plan === 'long';
    document.getElementById('soAmtBox').hidden = !isoLong;
    set('soAmtAdj', money.format(all.amtAdj));
    set('soAmt', money.format(all.amt));

    var note = document.getElementById('soNote'), notes = [];
    if (o.plan !== 'same' && o.price <= o.strike) notes.push('The options are not in the money at today’s price, so exercising now means paying at least the market price for the shares.');
    if (o.plan === 'same' && !all.exercised) notes.push('At the target price the options are worth nothing to exercise, because the strike price is at or above it.');
    if (o.plan !== 'same' && all.st + all.lt < 0) notes.push('This plan ends in a capital loss. Only up to $3,000 of net capital loss a year is deducted here; any excess would carry forward and is not counted.');
    if (o.type === 'iso' && o.plan !== 'long') notes.push('Selling ISO shares before the holding periods end is a disqualifying disposition, so the gain up to the exercise-date spread is taxed as ordinary income (without payroll tax).');
    note.hidden = !notes.length;
    note.textContent = notes.join(' ');

    // Value at other share prices.
    var prices = [o.price, o.target, o.target * 0.5, o.target * 0.75, o.target * 1.25, o.target * 1.5, o.target * 2];
    if (o.strike > 0) prices.push(o.strike);
    prices = prices.map(function (p) { return Math.round(p * 100) / 100; })
      .filter(function (p, i, a) { return a.indexOf(p) === i; }).sort(function (a, b) { return a - b; });
    document.getElementById('soPriceBody').innerHTML = prices.map(function (p) {
      var a = outcome(o, o.total, p), v = outcome(o, o.vested, p);
      var label = price.format(p) + (p === Math.round(o.target * 100) / 100 ? ' (target)' : p === Math.round(o.price * 100) / 100 ? ' (today)' : '');
      return '<tr><td>' + label + '</td><td>' + signed(v.pretax) + '</td><td>' + signed(a.pretax) + '</td><td>' +
        signed(a.tax) + '</td><td>' + signed(a.after) + '</td></tr>';
    }).join('');
    set('soPriceIntro', 'Each row sells at that price using your chosen plan' + (o.plan === 'same' ? '.' : ' (exercising today at ' + price.format(o.price) + ').') + ' Tax year ' + TAX_YEAR + ' rules.');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('soForm');
    if (!form) return;
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
